# Check all sheets for tables that might contain validation cohort data
# Look for tables with "Patient" and numbers > 80

for fname in ['supp.pdf', 'mmc2.pdf', 'mmc1.pdf']:
    if fname not in tables:
        continue
    for sname, sheet_obj in tables[fname].items():
        sheet_rows = sheet_obj.get('rows', [])
        if not sheet_rows:
            continue

        # Check if this sheet has patient data with high numbers
        has_high_patients = False
        for row in sheet_rows:
            for cell in row:
                if isinstance(cell, dict):
                    val = str(cell.get('value', ''))
                else:
                    val = str(cell)
                if 'Patient-' in val or 'Patient' in val:
                    try:
                        num = int(val.replace('Patient-', '').replace('Patient', ''))
                        if num > 80:
                            has_high_patients = True
                            break
                    except:
                        pass
            if has_high_patients:
                break

        if has_high_patients:
            print(f"Found high patient numbers in {fname}/{sname}")
            # Show first few rows
            for i in range(min(5, len(sheet_rows))):
                print(f"  Row {i+1}: {sheet_rows[i][:5]}")
            print()
